export default function (pi) {
  pi.registerTool({
    name: "late_input", label: "Late input", description: "Queue late input",
    parameters: { type: "object", properties: {} },
    async execute(_id, _params, _signal, _update, ctx) {
      while (!ctx.hasPendingMessages()) { await new Promise((resolve) => { setTimeout(resolve, 1); }); }
      return { content: [{ type: "text", text: "Queued." }], details: {} };
    },
  });
}
